def get_omega(m):
    if m == 0: return 0
    factors = set()
    d = 2
    temp = abs(m)
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return len(factors)

def count_pairs(n):
    import math
    # factorial n
    f = math.factorial(n)
    # 2023 = 7 * 17^2
    if f % 2023 != 0:
        return 0
    m = f // 2023
    return 2**get_omega(m)

